from pathlib import Path
import csv,json,hashlib
R=Path(r'E:\Project\FlexPPI\experiments\_sources\mel5_tcr_binding_20261028')
rows=list(csv.DictReader((R/'combined_binding_scores_wide.csv').open(encoding='utf-8-sig')))
byid={r['case_id']:r for r in rows}
models=['ERGO-II McPAS','ERGO-II VDJdb','NetTCR2.2 known-overlap-excluded','NetTCR2.2 all20','ImRex downsample','ImRex full']
relations=[]
for m in models:
 s={k:float(byid[k][m]) for k in ['3hg1','4jff','4jfd','4jfe']}
 relations.append({'configuration':m,'WT_ELA_score':s['3hg1'],'mature_ELA_score':s['4jff'],'G4A_score':s['4jfd'],'I7A_score':s['4jfe'],'mature_ELA_score_above_WT':s['4jff']>s['3hg1'],'G4A_score_below_mature_ELA':s['4jfd']<s['4jff'],'I7A_score_below_mature_ELA':s['4jfe']<s['4jff'],'core_four_reference_classes_at_0p5':['positive' if s[k]>=.5 else 'negative' for k in ['3hg1','4jff','4jfd','4jfe']]})
paths=[R/'imrex/training_membership_deeper_audit.json',R/'nettcr/training_membership_deeper_audit.json',R/'ergo/mature_sequence_training_recheck.json',R/'combined_binding_scores_wide.csv',R/'nettcr/known_CDR3_pair_training_overlap.csv']
audit={'question':'Do published models identify affinity ordering, and could matching training examples explain correct-looking score changes?','score_comparison':relations,'scope':'Observed raw binding classifier scores, not measured affinities or evidence for the causal origin of predictions. No retraining or new inference performed in this audit.','membership_findings':{'ImRex':'Both released actual training tables contain native MEL5 CDR3beta+ELA positive. Mature CDR3beta absent including common anchor-normalized forms. G4A and I7A peptides absent for every receptor. Nearest mature CDR3beta training sequence is native MEL5: 15 residues, edit distance4, 11 identical positions. No family exclusion.','NetTCR2.2':'Final models trained on limited34352 rows; full37721 rows used for evaluation. Native MEL5+ELA exact six-CDR input occurs in partition0. Mature alpha/beta CDR3 pair+ELA occurs but its A1/A2/B2 fields are native rather than engineered, so not a complete mature six-CDR exact duplicate. All11 known CDR3pair-related rows partition0. G4A/I7A peptides absent across both tables and peptide/original_peptide columns. t0 four models exclude partition0 from training and validation per official nested CV; no checkpoint-specific training-row manifest or full family-exclusion proof.','ERGO-II':'G4A/I7A peptides absent from both released checkpoint training pickles. Mature alpha/beta CDR3 absent under checked anchor forms. VDJdb contains native beta+ELA twice, one positive and one negative, both with a different alpha extension. Not two exact full-input positives. VDJdb nearest mature beta is native MEL5 at edit distance4; McPAS nearest distance6.'},'conclusion':'Cannot claim all mainstream predictors recover affinity ordering. No evidence of direct G4A/I7A exact peptide-label memorization in released tables. There is evidence of native/same-family training exposure; correct-looking score changes cannot establish family-independent generalization, and exposure alone does not prove a memorization cause.','sources':[{'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in paths]}
(R/'training_coverage_and_score_interpretation_audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2),encoding='utf-8')
text='''# 训练集覆盖核查与结论更正\n\n不能将前次结果概括为“主流模型能判定G4A和I7A亲和力差、α24β17亲和力好”。实际得到的是若干结合分类器的原始分数；训练目标主要是识别/结合标签，分数降低不是经过验证的KD降低，也未必表示模型判为不结合。原四态在SPR实验中均有可测结合。ImRex默认版对四态都给出高于0.5的分数，所谓方向正确只指成熟ELA分数高于两个肽替换态。NetTCR也呈现这个局部趋势，但其成熟ELA分数低于野生MEL5，未恢复亲和成熟的方向。\n\n| 配置 | 野生MEL5–ELA | 成熟ELA | G4A | I7A | 成熟高于野生 | G4A低于成熟 | I7A低于成熟 |\n|---|---:|---:|---:|---:|---|---|---|\n'''
for x in relations:
 text+='| '+x['configuration']+' | '+' | '.join(f"{x[k]:.6g}" for k in ['WT_ELA_score','mature_ELA_score','G4A_score','I7A_score'])+' | '+' | '.join('是' if x[k] else '否' for k in ['mature_ELA_score_above_WT','G4A_score_below_mature_ELA','I7A_score_below_mature_ELA'])+' |\n'
text+='''\n表中“是/否”只是同一配置内的描述性分数关系，不表示该分类器已预测对应的物理亲和力关系。也不将四个相关状态用于总体预测性能评估。\n\n## 已确认的训练覆盖\n\nImRex的两份实际训练表都含野生MEL5的CDR3β与ELA配对，标签为positive。成熟受体的CDR3β未出现，含或去两端C/F锚点的常见形式也未出现；G4A与I7A两条肽在任意受体配对下均未出现。可是成熟CDR3β最接近的训练序列正是其野生亲本MEL5，两条15残基序列中11个位置相同、编辑距离4。这里明确存在亲本/同家族训练覆盖，不能称家族独立测试；但没有找到“G4A、I7A的具体训练标签已经存入该训练表”的证据。\n\nNetTCR-2.2训练数据中的重叠更直接：野生MEL5–ELA是完整六CDR、肽、HLA都一致的阳性；成熟受体的双CDR3与ELA也有记录，但A1、A2、B2仍是野生序列，与工程化成熟受体不一致，因此重叠只精确到双CDR3等字段，不能称完整成熟输入重复。相关11行均位于分区0。主分析使用的t.0.v.1–4按官方嵌套交叉验证规则将分区0留作测试，不用于训练或验证；全20模型池中则包含受这些记录影响的模型。此处理只排除了已确认精确双CDR3记录，未证明所有近缘家族均被排除，公开包亦没有每个checkpoint的逐行训练清单。官方limited训练表34,352行、full评价表37,721行及官方CV中，G4A、I7A在peptide和original_peptide列均为0次。\n\nERGO-II的两个实际训练pickle中，G4A、I7A两条肽均未出现，成熟α/β CDR3及所核查锚点形式也均未出现。VDJdb训练中含野生β–ELA两条记录，一条positive、一条negative，且α链带不同末端延伸，不能将其称作两条完全相同输入的阳性。VDJdb中最接近成熟β的仍为野生MEL5，编辑距离4；McPAS最近距离为6。训练标签冲突与序列字段标准化差异也说明，不能只查PDB号或论文名称判断覆盖。\n\n## 能与不能作出的结论\n\n目前能确定的是：公开训练数据中存在野生MEL5及其成熟双CDR3等近缘覆盖；未发现G4A和I7A的精确肽标签直接泄漏。近缘覆盖使这些结果不足以证明严格的家族外泛化，却不单独证明评分下降由记忆造成。分数下降可能来自已学到的同家族识别模式，也可能来自对突变肽的组合外推或常见ELA相似性等因素；本核查没有区分这些来源，因此不作因果归因。\n\n若要评价整个MEL5家族之外的泛化，应在训练前按各模型实际输入界定并剔除该家族及相应近缘记录，重新训练后统一测试；若还要评价肽外推，应另说明是否剔除ELA及近似肽。只在推理时删除训练CSV里的几行而继续使用旧权重，不能消除已经学入权重的信息。需要同时保留原公开权重结果与这一重新训练条件，不能把处理前后的任务差异隐去。\n\n对3.4而言，现有这些分数只能作为带训练覆盖限制的回顾性背景对照，既不能据此宣称主流模型普遍失败，也不能声称它们已经独立预测了亲和力巨变。更可靠的主证据仍是残基动态预测与独立重复MD之间的具体对应，以及G4A中如实保留的不一致结果。结合态柔性本身不能给出总结合熵或证明亲和力变化的因果贡献。\n\n本次没有重跑模型、重训或修改论文正文。逐项证据见training_coverage_and_score_interpretation_audit.json及其中所列的三个模型深度审计文件，包含对应训练表SHA、命中计数、分区及最近邻序列。\n'''
(R/'训练集覆盖核查与结论更正.md').write_text(text,encoding='utf-8')
print(json.dumps({'memo':str(R/'训练集覆盖核查与结论更正.md'),'audit':str(R/'training_coverage_and_score_interpretation_audit.json'),'model_configs':len(relations),'direct_G4A_I7A_training_peptide_hits':0,'family_exclusion':'not established'},ensure_ascii=False,indent=2))
